import{_ as o,o as r,c as a,a2 as n}from"./chunks/framework.DGvnA5EY.js";const s="/workbuddy-guide/assets/01-official-three-compare.BQu7F5yM.png",e="/workbuddy-guide/assets/05-expert-vs-team.Be5k2dCk.png",l="/workbuddy-guide/assets/02-official-expert-team-card.740DUHnV.png",d="/workbuddy-guide/assets/03-official-expert-team-run.B92oXCrK.png",i="/workbuddy-guide/assets/04-official-expert-search-pin.B2WjrOY8.png",m=JSON.parse('{"title":"第 6 章 专家和专家团","description":"> 内容来源：WorkBuddy 官方指南 · 专家（非官方整理，© 本指南作者，保留所有权利） 第 5 章你装好了 Skill —— 那解决了\\"AI 能做什么\\"。这一章解决另一个问题： \\"让谁来做\\"。同一件事，让\\"有 10 年经验的文案\\"和\\"刚入职的新人\\"来做， 结果质量差很远…","frontmatter":{"title":"第 6 章 专家和专家团"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 6 章 专家和专家团/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 6 章 专家和专家团/index.md","lastUpdated":1791615980000}'),g={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 6 章 专家和专家团/index.md"};function h(u,t,p,q,b,c){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="第-6-章-专家和专家团" tabindex="-1">第 6 章 专家和专家团 <a class="header-anchor" href="#第-6-章-专家和专家团" aria-label="Permalink to &quot;第 6 章 专家和专家团&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 专家（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>第 5 章你装好了 Skill —— 那解决了&quot;AI 能做什么&quot;。这一章解决另一个问题： &quot;<strong>让谁来做</strong>&quot;。同一件事，让&quot;有 10 年经验的文案&quot;和&quot;刚入职的新人&quot;来做， 结果质量差很远。专家和专家团就是给 AI <strong>换个身份</strong>的机制。</p><h2 id="一、先搞清楚-专家、专家团和-skill-到底什么关系" tabindex="-1">一、先搞清楚：专家、专家团和 Skill 到底什么关系 <a class="header-anchor" href="#一、先搞清楚-专家、专家团和-skill-到底什么关系" aria-label="Permalink to &quot;一、先搞清楚：专家、专家团和 Skill 到底什么关系&quot;">​</a></h2><p>这是本章最该先弄明白的问题。很多人把三者搞混，结果该用专家的时候 去装技能，该用技能的时候去召唤专家团。</p><p>官方给的这张图建议先看：</p><p><img src="'+s+'" alt="官方对比图：Skill 是工具能力，专家是工具能力加领域经验，专家团是多位专家加协作流程" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>官方给的一句话总结最精辟：</p><blockquote><p><strong>Skill 是能力 → 专家是能力+经验 → 专家团是多位专家+协作流程</strong></p></blockquote><h3 id="怎么选-官方表格" tabindex="-1">怎么选（官方表格） <a class="header-anchor" href="#怎么选-官方表格" aria-label="Permalink to &quot;怎么选（官方表格）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Skill</th><th>专家（Agent 型）</th><th>专家团（Team 型）</th></tr></thead><tbody><tr><td><strong>组成关系</strong></td><td>工具能力：让 AI 能做某件事</td><td>AI 顾问：懂某个领域的 AI 角色</td><td>AI 协作团队：自动拆解、并行执行、完整交付</td></tr><tr><td><strong>怎么选</strong></td><td>需要 AI 具备某种工具能力</td><td>有一个明确的单点问题</td><td>任务复杂，需要多角色配合</td></tr></tbody></table><p>三个白话场景：</p><table tabindex="0"><thead><tr><th>你要做的</th><th>选哪个</th></tr></thead><tbody><tr><td>让 AI 能看合同审查（附带风险）</td><td><strong>装 Skill</strong></td></tr><tr><td>给我一份 SEO 优化方案</td><td><strong>召唤专家</strong></td></tr><tr><td>7 人并行做一轮内容营销，从关键词到转化报告全搞定</td><td><strong>召唤专家团</strong></td></tr></tbody></table><p><img src="'+e+'" alt="上面是单个专家专注做一件事，下面是多位专家分工后由团长汇总交付" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解专家与专家团的差别，与实际软件界面无关。</em></p><h2 id="二、专家是「角色切换」-专家团是「协作执行」" tabindex="-1">二、专家是「角色切换」，专家团是「协作执行」 <a class="header-anchor" href="#二、专家是「角色切换」-专家团是「协作执行」" aria-label="Permalink to &quot;二、专家是「角色切换」，专家团是「协作执行」&quot;">​</a></h2><h3 id="专家-角色切换机制" tabindex="-1">专家 = 角色切换机制 <a class="header-anchor" href="#专家-角色切换机制" aria-label="Permalink to &quot;专家 = 角色切换机制&quot;">​</a></h3><p>以「<strong>人设 + 方法论 + 工具链</strong>」让 WorkBuddy 用特定领域专家身份执行任务。 比如你召唤一个&quot;文档评审官&quot;，它就会用评审官的视角去看你的文档。</p><h3 id="专家团-协作执行机制" tabindex="-1">专家团 = 协作执行机制 <a class="header-anchor" href="#专家团-协作执行机制" aria-label="Permalink to &quot;专家团 = 协作执行机制&quot;">​</a></h3><p>由<strong>多位专家分工协作</strong>，由团长自动拆解、并行执行并整合交付。 你只需要描述目标，它自己拆任务、分配给不同专家、最后汇总。</p><h3 id="一个重要的安全边界" tabindex="-1">一个重要的安全边界 <a class="header-anchor" href="#一个重要的安全边界" aria-label="Permalink to &quot;一个重要的安全边界&quot;">​</a></h3><p>官方明确写了：</p><blockquote><p>专家本身<strong>不主动获取系统权限</strong>，仅处理你主动提供的对话与上传文件。 <strong>当配备了 Skill / MCP 时</strong>才会在你的授权下间接访问文件或外部服务。</p></blockquote><p>也就是说，<strong>召唤专家不会自动获得你的文件访问权</strong>。它能碰到什么， 取决于你有没有给它配 Skill 或连接器。</p><h2 id="三、使用专家-4-步" tabindex="-1">三、使用专家：4 步 <a class="header-anchor" href="#三、使用专家-4-步" aria-label="Permalink to &quot;三、使用专家：4 步&quot;">​</a></h2><h3 id="第-1-步-进入专家中心" tabindex="-1">第 1 步：进入专家中心 <a class="header-anchor" href="#第-1-步-进入专家中心" aria-label="Permalink to &quot;第 1 步：进入专家中心&quot;">​</a></h3><p>打开左侧导航栏的**「专家·技能·连接器」<strong>，默认进入</strong>专家**页签。</p><h3 id="第-2-步-选专家或专家团" tabindex="-1">第 2 步：选专家或专家团 <a class="header-anchor" href="#第-2-步-选专家或专家团" aria-label="Permalink to &quot;第 2 步：选专家或专家团&quot;">​</a></h3><p>浏览卡片，查看能力介绍和任务示例。</p><ul><li><strong>专家</strong>卡片展示：能力介绍、擅长领域、任务示例</li><li><strong>专家团</strong>卡片展示：能力介绍、擅长领域、<strong>团队成员</strong>、任务示例</li></ul><p><img src="'+l+'" alt="专家团卡片：展示能力介绍、擅长领域、团队成员和任务示例" loading="lazy"></p><p><em>此图片来自官方。</em></p><h3 id="第-3-步-召唤" tabindex="-1">第 3 步：召唤 <a class="header-anchor" href="#第-3-步-召唤" aria-label="Permalink to &quot;第 3 步：召唤&quot;">​</a></h3><p>点「召唤专家」或「召唤专家团」，进入对话界面。</p><h3 id="第-4-步-描述任务" tabindex="-1">第 4 步：描述任务 <a class="header-anchor" href="#第-4-步-描述任务" aria-label="Permalink to &quot;第 4 步：描述任务&quot;">​</a></h3><p><strong>专家</strong>：把任务告诉它，它会按照该角色的专业视角和方法完成。</p><p><strong>专家团</strong>：用自然语言描述目标，专家团团长自动拆解、分配、执行并返回完整结果。</p><p><img src="'+d+'" alt="专家团执行：团长自动拆解任务、分配给成员、并行执行后汇总" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="四、快速找到专家-搜索与置顶" tabindex="-1">四、快速找到专家：搜索与置顶 <a class="header-anchor" href="#四、快速找到专家-搜索与置顶" aria-label="Permalink to &quot;四、快速找到专家：搜索与置顶&quot;">​</a></h2><p>在对话中点击专家入口，会展开<strong>最近使用</strong>的专家下拉列表，提供两种快捷方式：</p><table tabindex="0"><thead><tr><th>方式</th><th>作用</th></tr></thead><tbody><tr><td><strong>搜索</strong></td><td>输入名称关键字快速查找专家，点击即可召唤</td></tr><tr><td><strong>置顶</strong></td><td>把常用专家置顶，<strong>结果会持久保存</strong>，下次打开排在列表前部</td></tr></tbody></table><p><img src="'+i+'" alt="专家下拉列表里的搜索框和置顶功能" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>新手建议</strong>：把 2-3 个常用的置顶，省得每次翻列表。</p><h3 id="一个坑-专家团会话中不能直接换专家" tabindex="-1">一个坑：专家团会话中不能直接换专家 <a class="header-anchor" href="#一个坑-专家团会话中不能直接换专家" aria-label="Permalink to &quot;一个坑：专家团会话中不能直接换专家&quot;">​</a></h3><p>在<strong>专家团</strong>会话里搜索召唤其他专家时，会提示： 「当前会话已使用专家团，切换其他专家需要开启新对话」。</p><p>确认后会先回到新对话态再完成召唤，<strong>新专家不会回绑到当前专家团会话</strong>。 所以如果你想换专家，得开新对话，别指望在专家团会话里直接切。</p><h2 id="五、专家依赖的服务没连接怎么办" tabindex="-1">五、专家依赖的服务没连接怎么办 <a class="header-anchor" href="#五、专家依赖的服务没连接怎么办" aria-label="Permalink to &quot;五、专家依赖的服务没连接怎么办&quot;">​</a></h2><p>部分专家执行任务时会依赖 MCP 或连接器（比如腾讯文档、TAPD）。 当任务执行过程中需要某个<strong>尚未连接</strong>的服务时，WorkBuddy 会在<strong>输入框上方</strong> 展示连接引导卡片，显示服务名称和头像。</p><ul><li>点卡片上的<strong>连接</strong>，按提示完成授权后，WorkBuddy 会<strong>自动继续当前任务</strong>， <strong>无需重新发起对话</strong></li><li>连接引导<strong>只在任务实际用到该服务时才出现</strong>，不会在会话开始时一次性罗列全部依赖</li></ul><p>这个设计挺贴心：不会一上来就给你列一堆要授权的东西，用到了才问。</p><h2 id="六、创建你自己的专家" tabindex="-1">六、创建你自己的专家 <a class="header-anchor" href="#六、创建你自己的专家" aria-label="Permalink to &quot;六、创建你自己的专家&quot;">​</a></h2><p><strong>什么情况下值得创建</strong>：你有明确任务和工作方法，希望<strong>重复使用</strong>专业能力。 <strong>如果只是临时完成一次简单任务，直接用普通对话即可</strong>，不用专门创建。</p><h3 id="创建步骤" tabindex="-1">创建步骤 <a class="header-anchor" href="#创建步骤" aria-label="Permalink to &quot;创建步骤&quot;">​</a></h3><ol><li>在<strong>专家·技能·连接器 → 专家</strong>页，点右上角**「我的专家」**</li><li>点**「创建专家」**，系统自动进入创建对话，由内置的专家管理工具引导你完成配置 ——<strong>无需额外安装或操作</strong></li><li>按对话指令配置专家</li></ol><h3 id="配置建议-官方给的要点" tabindex="-1">配置建议（官方给的要点） <a class="header-anchor" href="#配置建议-官方给的要点" aria-label="Permalink to &quot;配置建议（官方给的要点）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>填什么</th><th>反面例子</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>短角色名，便于识别和召唤</td><td>&quot;专家1&quot;、&quot;助手&quot;（无指向的名称）</td></tr><tr><td><strong>人设身份</strong></td><td><strong>是谁 + 有什么背景</strong></td><td>&quot;帮我写代码&quot;（写成了任务本身）</td></tr><tr><td><strong>擅长领域</strong></td><td>写清边界，同时说明&quot;做什么&quot;和**&quot;不做什么&quot;**</td><td>&quot;什么都行&quot;</td></tr><tr><td><strong>提示词</strong></td><td>工作流程、输出格式与约束，能举例最好</td><td>只写&quot;您是一个专家&quot;</td></tr></tbody></table><h3 id="两个必知的限制" tabindex="-1">两个必知的限制 <a class="header-anchor" href="#两个必知的限制" aria-label="Permalink to &quot;两个必知的限制&quot;">​</a></h3><ul><li><strong>创建后无法修改名称</strong> —— 想换名字只能重新创建。所以起名要慎重。</li><li><strong>这是创建给自己（或团队成员）用的</strong> —— 要上架到专家市场供所有人召唤， 得按规范打包专家包并提交，那是另一套流程。</li></ul><h3 id="管理专家" tabindex="-1">管理专家 <a class="header-anchor" href="#管理专家" aria-label="Permalink to &quot;管理专家&quot;">​</a></h3><p>在<strong>我的专家</strong>列表里，点卡片右上角召唤旁的<strong>三个点</strong>：</p><table tabindex="0"><thead><tr><th>操作</th><th>用途</th></tr></thead><tbody><tr><td><strong>修改专家</strong></td><td>输出不符合预期时，从角色定位、任务范围、工作方法、输入要求等方面优化</td></tr><tr><td><strong>分享</strong></td><td>生成链接给团队成员。<strong>只是分享链接，不上架市场</strong>；成员召唤的是<strong>副本</strong>，不影响你的配置</td></tr><tr><td><strong>删除</strong></td><td><strong>无法恢复，请谨慎</strong>。若已分享给成员，删除后对方将无法继续使用</td></tr></tbody></table><h2 id="七、一个坑-专家团的积分消耗高得多" tabindex="-1">七、一个坑：专家团的积分消耗高得多 <a class="header-anchor" href="#七、一个坑-专家团的积分消耗高得多" aria-label="Permalink to &quot;七、一个坑：专家团的积分消耗高得多&quot;">​</a></h2><p>官方提示：<strong>专家团会并行调用多位专家、涉及多轮模型交互，积分消耗通常为 单专家的 3–5 倍</strong>（以实际任务为准）。</p><p><strong>应对</strong>：召唤专家团前先看积分余额，<strong>别让任务执行到一半因为积分不足中断</strong>。</p><h2 id="八、本章动手-召唤一次-再对比一次" tabindex="-1">八、本章动手：召唤一次，再对比一次 <a class="header-anchor" href="#八、本章动手-召唤一次-再对比一次" aria-label="Permalink to &quot;八、本章动手：召唤一次，再对比一次&quot;">​</a></h2><ol><li>打开<strong>专家·技能·连接器 → 专家</strong>，随便点一个专家，召唤它</li><li>用一个你真实的问题问它，看它的视角和普通对话有什么不同</li><li>把常用专家<strong>置顶</strong>一个</li><li>如果有空，召唤一次<strong>专家团</strong>，感受它自动拆解的过程 （<strong>先看积分余额</strong>）</li></ol><h2 id="九、本章任务清单-做完就算过关" tabindex="-1">九、本章任务清单（做完就算过关） <a class="header-anchor" href="#九、本章任务清单-做完就算过关" aria-label="Permalink to &quot;九、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 能说出 Skill、专家、专家团三者的区别（能力 / 能力+经验 / 多专家+流程）</li><li>[ ] 知道专家不会主动拿你的文件权限（除非配了 Skill 或连接器）</li><li>[ ] 召唤过一次专家，并说出它和普通对话的差别</li><li>[ ] 把至少一个常用专家置顶</li><li>[ ] 知道专家团会话里不能直接换专家，得开新对话</li><li>[ ] 召唤专家团前会先看积分余额（3-5 倍消耗）</li><li>[ ] 知道专家创建后名字改不了，起名要慎重</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章概念多，这里统一解释。</p></blockquote><p><strong>专家（Agent 型）</strong> 给 AI <strong>换一个人设和专业身份</strong>。召唤一个&quot;文档评审官&quot;，它就用评审官的 视角和方法看你的稿子。它换的是&quot;<strong>是谁在思考</strong>&quot;，不是&quot;能做什么&quot;。</p><p><strong>专家团（Team 型）</strong><strong>多个专家协作</strong>。你给一个复杂目标，团长自动拆解任务、分配给不同成员、 并行执行、最后汇总交付。换的是&quot;<strong>几个专业的人一起干</strong>&quot;。</p><p><strong>人设 + 方法论 + 工具链</strong> 专家的三个组成：</p><ul><li><strong>人设</strong>：我是谁（10 年经验的工程师）</li><li><strong>方法论</strong>：我怎么做事（先看架构再看代码）</li><li><strong>工具链</strong>：我能调用什么（配了哪些 Skill）</li></ul><p>专家<strong>本身不自带权限</strong>。只有配上工具链（Skill/连接器），它才能碰到外部东西。</p><p><strong>SOP 编排</strong> 专家团的工作流程：谁先做、谁后做、怎么配合。官方定义是 &quot;<strong>专家团 = 多位专家 + SOP 编排</strong>&quot;。</p><p><strong>并行执行</strong> 多个任务<strong>同时</strong>跑，不是排队等。所以快，但也更耗积分。</p><p><strong>我的专家</strong> 你创建的专家列表。在专家页右上角点进去。</p><p><strong>创建专家</strong> 用<strong>对话引导</strong>的方式配置——系统会一步步问你，你可以直接采用它给的示例， 也可以按自己的任务改。<strong>不需要写代码，也不需要额外安装。</strong></p><p><strong>专家名不可改</strong> 创建后名字<strong>改不了</strong>，想换只能重建。所以别叫&quot;专家1&quot;。</p><p><strong>修改 vs 删除</strong></p><ul><li><strong>修改</strong>：优化配置（角色、范围、方法、输入要求），可反复改</li><li><strong>删除</strong>：<strong>永久消失，不可恢复</strong>。已分享给别人的，对方也用不了了</li></ul><p><strong>分享专家 vs 上架市场</strong></p><ul><li><strong>分享</strong>：生成一个链接发给同事，他们召唤的是<strong>副本</strong>，你的配置不受影响</li><li><strong>上架</strong>：放到专家市场让所有人能搜到，要按官方规范打包提交</li></ul><p><strong>置顶</strong> 把常用专家固定在列表前面，<strong>结果会持久保存</strong>，下次打开还在。 相当于给常用联系人设星标。</p><p><strong>MCP</strong> 一个让外部工具接入的标准协议。你可以在别处看到这个词，作用是 &quot;让 AI 能连到某个服务&quot;。第 7 章讲连接器时会再遇到。</p><p><strong>积分消耗倍数</strong> 专家团要调多个专家、多轮交互，消耗是单专家的 3-5 倍。 <strong>召唤前先看余额</strong>，否则做到一半可能因积分不足中断。</p><hr><p><em>下一篇：第 7 章 使用连接器——把外部邮箱、文档、IM 接进来。</em></p>',93)])])}const f=o(g,[["render",h]]);export{m as __pageData,f as default};
